// Presentation adapter for the existing /summary contract; no API or storage writes.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const object=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};
const count=v=>Number.isSafeInteger(v)&&v>=0?v:null;
const show=v=>count(v)===null?'미제공':v.toLocaleString('ko-KR');
const states={pending:'분석 대기',stale:'변경 · 재분석 필요',running:'분석 중',paused:'일시정지',rate_limited:'요청 제한 대기',review_required:'관리자 확인 필요',completed:'완료',failed:'오류',stopped:'중단',unknown:'결과 미확정'};
const reasons={rate_limited:'외부 서비스 요청 제한',limits_unconfirmed:'호출 한도 확인 필요',manual_reconciliation_required:'미확정 호출 확인 필요',request_outcome_unknown:'호출 결과 미확정 · 자동 재호출 안 함',provider_resume_required:'외부 서비스 중단 상태',invalid_model_output:'모델 응답 형식 확인 필요',invalid_date:'날짜 형식 확인 필요',daily_request_limit:'일일 요청 한도 도달',daily_album_limit:'일일 앨범 한도 도달',daily_token_limit:'일일 토큰 한도 도달',minute_wait:'호출 간격 대기',usage_unknown:'사용량 확인 필요',catalog_sync_failed:'입력 동기화 오류'};
Object.assign(reasons,{ready:'실행 조건 충족',not_enabled:'무인 분석 미활성',automation_disabled:'자동 동기화 중지 설정',incremental_sync_not_configured:'기존 증분 동기화 연결 필요',incremental_sync_held:'증분 동기화 보류',unattended_limits_changed:'승인된 시험 한도와 불일치',sync_already_running:'입력 동기화 진행 중',worker_busy:'기존 Worker 처리 중',unattended_connection_error:'무인 분석 연결 확인 필요'});
const reason=v=>reasons[v]||(typeof v==='string'&&/^[a-z][a-z0-9_]{0,79}$/.test(v)?'오류 코드: '+v:'서버 상태 확인 필요');
const when=v=>typeof v==='number'&&Number.isFinite(v)&&v>0&&v<8640000000000?new Date(v*1000).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'미제공';
export function aiOperationStatus(data){
 const root=object(data),d=Object.keys(object(root.dashboard)).length?root.dashboard:root,s=object(d.states),reviews=object(d.reviews),usage=object(d.usage);
 const jobs=Array.isArray(root.jobs)?root.jobs.filter(x=>x&&typeof x==='object'&&!Array.isArray(x)):null;
 const unknown=Array.isArray(root.unresolved_calls)?root.unresolved_calls:null;
 const progress=typeof d.progress==='number'&&Number.isFinite(d.progress)&&d.progress>=0&&d.progress<=100?d.progress:null;
 return {d,s,reviews,usage,jobs,unknown,progress,running:Boolean(jobs?.some(j=>j.state==='running')),sync:object(root.sync)};
}
export function renderAiOperationStatus(data){
 const m=aiOperationStatus(data),cards=[['분석 대상',m.d.total],['분석 대기',m.s.pending],['변경 · 재분석 필요',m.s.stale],['관리자 확인 필요',m.s.review_required],['완료',m.s.completed],['분석 오류',m.s.failed]];
 const card=(label,value)=>`<article class="vr-ai-summary-group"><h4>${label}</h4><p>${show(value)}</p></article>`;
 const progress=m.progress===null?'<p>진행률: 서버 미제공</p>':`<p>분석 진행률 ${m.progress}%</p><progress max="100" value="${m.progress}" aria-label="서버 분석 진행률" style="width:100%;accent-color:#b69a64"></progress>`;
 const waiting=m.jobs?.filter(j=>['paused','failed','rate_limited','unknown'].includes(j.state)||j.last_error);
 const jobs=m.jobs===null?'<p>작업 정보: 서버 미제공</p>':m.jobs.length?`<p>최근 작업 ${m.jobs.length}건 · 서버 조회 범위, 전체 작업 수와 다를 수 있습니다.</p><div class="table-wrap"><table><thead><tr><th>대상</th><th>상태</th><th>분석 대기 / 검토 필요 / 오류</th><th>확인 사항</th></tr></thead><tbody>${m.jobs.slice(0,200).map(j=>{const c=object(j.counts);return `<tr><td>${esc(String(j.artist||'대상 미제공').slice(0,150))}</td><td>${esc(states[j.state]||'알 수 없는 상태')}</td><td>${show(c.pending)} / ${show(c.review_required)} / ${show(c.failed)}</td><td>${j.last_error?esc(reason(j.last_error)):'—'}${j.state==='rate_limited'?`<br>다음 허용: ${esc(when(j.retry_at))}`:''}</td></tr>`;}).join('')}</tbody></table></div>`:'<p>반환된 작업 없음 · 자동 분석이 활성화됐다는 뜻은 아닙니다.</p>';
 const warnings=[];
 if(m.unknown?.length)warnings.push(`결과 미확정 호출 ${m.unknown.length}건이 반환됐습니다. 자동 재호출하지 않습니다.`);
 if(waiting?.length)warnings.push(`중단·오류·확인이 필요한 작업 ${waiting.length}건이 반환됐습니다.`);
 if(count(m.s.review_required)>0)warnings.push(`분석 결과를 검토할 앨범 ${show(m.s.review_required)}건이 있습니다. 아래 기존 AI 앨범 분류 관리에서 확인하세요.`);
 const syncState=states[m.sync.state]||({idle:'대기',completed:'완료',held:'보류',not_enabled:'미활성'}[m.sync.state])||'서버 미제공';
 return `<section class="vr-autofill-progress" aria-label="Gemini AI 분석"><h3>Gemini AI 분석</h3><div class="vr-autofill-grid" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,125px),1fr))">${[['분석 대기',m.s.pending],['관리자 확인 필요',m.s.review_required],['분석 오류',m.s.failed],['결과 미확정 호출',m.unknown===null?null:m.unknown.length]].map(([l,v])=>`<div class="vr-autofill-item"><span>${l}</span><strong class="vr-autofill-number">${show(v)}</strong></div>`).join('')}</div><details data-vr-summary-detail="gemini"><summary>Gemini 분석 작업 상세</summary><p class="vr-admin-caution" data-ai-summary-state>응답 정상 · 서버 집계만 표시합니다. Gemini 분석 진행률은 자동 보완 또는 Catalog 반영률이 아닙니다.</p>${progress}<div class="vr-ai-summary-grid" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,140px),1fr))">${cards.map(([l,v])=>card(l,v)).join('')}</div><section aria-label="확인 필요"><h4>확인 필요</h4>${warnings.length?warnings.map(x=>'<p>'+esc(x)+'</p>').join(''):'<p>제공된 정보에서 확인 항목이 없습니다. 미제공 정보를 정상으로 판정하지 않습니다.</p>'}</section><section aria-label="분석 작업"><h4>분석 작업</h4>${jobs}</section><details data-vr-summary-detail="gemini-sync"><summary>호출·동기화 상태</summary><p>입력 동기화: ${esc(syncState)} · 입력 동기화와 Gemini 자동 분석은 별개입니다.</p><p>무인 자동 분석: ${m.d.auto_analysis?.version===1?esc(({running:'활성',held:'보류',not_enabled:'미활성'}[m.d.auto_analysis.state]||'상태 확인 필요')+' · '+reason(m.d.auto_analysis.reason)):'서버 연결 상태 미제공 · 활성화 미확인'}</p><p>자동 분석 Worker: ${m.d.worker_connection?.version===1?(m.d.worker_connection.started===true?'기동됨 · 기존 한도·작업 상태에 따라 처리':m.d.worker_connection.enabled===true?'작업 시작 대기':'비활성'):'연결 상태 미제공'}</p><p>오늘 요청 ${show(m.usage.requests)} · 요청 오류 ${show(m.usage.failed_requests)} · 요청 제한 ${show(m.usage.rate_limits)}</p><p>검토 대기 제안 ${show(m.reviews.pending)} · 제안 확인 ${show(m.reviews.confirmed)} · 반려 ${show(m.reviews.rejected)}</p></details><p class="vr-admin-caution">조회만 수행합니다. 검토 저장·확정·Catalog 반영 및 Gemini 호출을 실행하지 않습니다.</p></details></section>`;
}

export function renderAutofillProgress(data) {
 const o=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};
 const num=v=>Number.isSafeInteger(v)&&v>=0?v:null;
 const show=v=>num(v)===null?'—':v.toLocaleString('ko-KR');
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=v=>typeof v==='number'&&Number.isFinite(v)&&v>0&&v<8640000000000?new Date(v*1000).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'—';
 const pct=(v,n)=>num(v)!==null&&num(n)!==null&&n>0&&v<=n?(v/n*100).toFixed(1)+'%':'—';
 const a=o(data?.autofill_progress),d=o(a.snapshot),t=o(d.totals),f=o(d.fields),l=o(d.ledger),day=o(l.last_24h),all=o(l.all),source=o(d.source_last_24h),providers=o(source.provider_capture_observations),labels=o(source.label_provenance_completed_event_counts);
 const wrap=(body)=>'<section class="vr-autofill-progress" aria-label="자동 보완 진척 현황"><h3>신뢰 출처 기반 자동 보완 현황</h3>'+body+'</section>';
 const placeholder=(message)=>wrap(`<p role="status">${message}</p><div class="vr-autofill-grid">${['Album Type','Label','Original Year','Genre'].map(n=>`<div class="vr-autofill-item"><div class="vr-autofill-line"><span>${n}</span><strong>—%</strong></div><p>등록 — / 미등록 —</p></div>`).join('')}</div><p>—는 미제공 수치이며 0건을 뜻하지 않습니다.</p>`);
 if(a.version!==1)return placeholder('자동 보완 집계 미제공 · NAS 연동 필요');
 if(d.state!=='ADMIN_AUTOFILL_PROGRESS_OBSERVED')return placeholder(a.state==='refreshing'?'자동 보완 집계 중 · 기존 분석은 계속 진행됩니다.':'자동 보완 집계 미확인 · 새로고침으로 확인하세요.');
 const total=num(t.catalog_active);
 const field=(key,name)=>{const n=num(o(f[key]).effective_empty),filled=total!==null&&n!==null&&n<=total?total-n:null,p=pct(filled,total);return `<div class="vr-autofill-item"><div class="vr-autofill-line"><span>${name}</span><strong>${p}</strong></div>${p==='—'?'':`<progress max="100" value="${p.slice(0,-1)}" aria-label="${name} 등록률"></progress>`}<p>등록 ${show(filled)} / ${show(total)} · 미등록 ${show(n)}</p><p>입력 일치 슬롯 ${show(o(f[key]).aligned_available_slot)} · 재시도 보류 ${show(o(f[key]).cooldown_deferred_slot)}</p></div>`;};
 const metric=(name,v,unit='')=>`<div class="vr-autofill-item"><span>${name}</span><strong class="vr-autofill-number">${show(v)}${num(v)===null?'':unit}</strong></div>`;
 const typeOrigin=o(o(f.type).provenance),originKeys=['default_studio','reference_marker','trusted_autofill_marker','other_folder','other_populated','unregistered'];
 const originKnown=total!==null&&originKeys.every(k=>num(typeOrigin[k])!==null)&&originKeys.reduce((sum,k)=>sum+typeOrigin[k],0)===total;
 const typeOriginHtml=originKnown?`<div class="vr-autofill-grid">${metric('Studio 기본값 · 미검증',typeOrigin.default_studio,'장')}${metric('기존 Reference 등록',typeOrigin.reference_marker,'장')}${metric('Trusted Autofill 표시',typeOrigin.trusted_autofill_marker,'장')}${metric('기타 폴더 기반 유형',typeOrigin.other_folder,'장')}</div><p>기타 등록 ${show(typeOrigin.other_populated)}장 · 미등록 ${show(typeOrigin.unregistered)}장. 기본값 수는 오류 확정 수가 아닙니다. 출처 표시는 독립 검증 완료율이 아닙니다.</p>`:'<p>Album Type 출처별 집계 미제공 또는 불일치</p>';
 const studioCounts=window=>{const v=o(window.default_studio_verification),confirmed=num(v.confirmed),corrected=num(v.corrected),matched=num(window.audit_matched_operations);return confirmed!==null&&corrected!==null&&matched!==null&&Number.isSafeInteger(confirmed+corrected)&&confirmed+corrected<=matched?{confirmed,corrected}:null;};
 const studioAll=studioCounts(all),studioDay=studioCounts(day);
 const studioHtml=`<div class="vr-autofill-grid">${metric('Studio 기존 유형 확인 · 누적',studioAll?.confirmed,'건')}${metric('Studio 유형 오류 교정 · 누적',studioAll?.corrected,'건')}${metric('기존 유형 확인 · 최근 24시간',studioDay?.confirmed,'건')}${metric('유형 오류 교정 · 최근 24시간',studioDay?.corrected,'건')}</div><p>검증·교정은 원장과 감사 기록이 일치한 채택 건수입니다. 미등록 유형 보완과 다르며 누적 채택 기록에 포함됩니다. —는 집계 미제공 또는 불일치입니다.</p>`;
 const cooldown=Array.isArray(d.source_cooldowns)?d.source_cooldowns.filter(x=>['musicbrainz.org','api.discogs.com','music.bugs.co.kr','maniadb.com'].includes(x?.host)&&typeof x.retry_at==='number'&&x.retry_at*1000>Date.now()).map(x=>`${esc(x.host)} · ${num(x.http_status)===null?'일시 대기':`HTTP ${show(x.http_status)}`} · ${esc(fmt(x.retry_at))} KST까지 (측정 기록)`).join('<br>'):null;
 const response=(key,name)=>{const p=o(providers[key]);return `<p>${name} · 관측 응답 ${show(p.observed_responses)} · 503 기록 ${show(num(p.observed_responses)===null?null:(p.status_503??0))}</p>`;};
 const feed=o(d.after),cursor=o(feed.ai_cursor),sync=typeof feed.catalog_feed_id==='string'&&typeof cursor.feed_id==='string'&&num(feed.catalog_seq)!==null&&num(cursor.seq)!==null?(feed.catalog_feed_id===cursor.feed_id?(feed.catalog_seq===cursor.seq?'일치':'차이 있음'):'Feed 불일치'):'미확인';
 const status=a.state==='refreshing'?'갱신 중 · 이전 집계':a.state==='stale'?'오래된 집계 · 갱신 실패/대기':a.state==='ready'?'캐시 집계':'상태 미확인';
 const held=o(day.held_reasons),known=day.states?.held;
 const reason=(k)=>num(known)===null?null:(held[k]??0);
 return wrap(`<p role="status">${status} · 측정 완료 ${esc(fmt(Date.parse(d.observed_at_kst)/1000))} KST · 집계 경계 ${d.boundary_unchanged===true?'변동 없음':d.boundary_unchanged===false?'변동 감지 (순차 관측)':'미확인'}</p><div class="vr-autofill-grid">${field('type','Album Type')}${field('label','Label')}${field('year','Original Year')}${field('genre','Genre')}</div><p>등록률은 정보 존재율이며 검증 완료율이 아닙니다. Genre는 Catalog SQL 장르 기준입니다.</p><h4>자동 보완 성과</h4><div class="vr-autofill-grid">${metric('최근 24시간 채택 기록',day.audit_matched_operations,'건')}${metric('누적 채택 기록',all.audit_matched_operations,'건')}${metric('입력 일치 · 보완 슬롯',t.aligned_albums_with_slot,'장')}${metric('재시도 cooldown 보류',t.cooldown_deferred_albums,'장')}</div><p>최근 24시간 시도 ${show(day.attempts)}건 · 채택률 ${pct(day.audit_matched_operations,day.attempts)} · 요청 예약 ${show(day.request_reservations)}건</p><p>슬롯은 외부 근거 검증 전 후보입니다. 보류 앨범은 다른 필드에 실행 슬롯이 있을 수 있습니다. 채택 기록은 원장·감사 일치 기준이며 자동 실행 출처의 독립적 증거는 아닙니다.</p><h4>외부 정보 수집 · 최근 24시간</h4>${response('musicbrainz','MusicBrainz')}${response('discogs','Discogs')}<p>보존 증거 재평가: 별도 실행 건수 미제공</p><details data-vr-summary-detail="type-origin"><summary>Album Type 출처 · Studio 검증 및 교정</summary>${typeOriginHtml}${studioHtml}</details><details data-vr-summary-detail="autofill-source"><summary>외부 출처 · 보류 및 정합성</summary><p>${cooldown===null?'Cooldown 상태 미확인':cooldown||'측정 기록상 현재 유효한 cooldown 없음 (실시간 아님)'}</p><p>일시 장애 대기 ${show(reason('source_temporary_retry_after'))} · 재시도 소진 ${show(reason('source_temporary_retry_exhausted'))} · 작품 근거 부족 ${show(reason('no_verified_work_evidence'))}</p><p>최근 24시간 Label 채택 이벤트 · 추정 ${show(num(source.matched_result_events)===null?null:(labels.estimated??0))} / 검증 ${show(num(source.matched_result_events)===null?null:(labels.verified??0))} / 미구분 ${show(num(source.matched_result_events)===null?null:(labels.unspecified??0))} · 결과 이벤트 일치 ${show(source.matched_result_events)}건</p><p>활성 Catalog ${show(total)} · AI ${show(t.ai_active)} · 공통 ${show(t.common_active)} · 입력 일치 ${show(t.input_aligned_all)} (${pct(t.input_aligned_all,total)})</p><p>증분 커서 ${sync} · Catalog ${show(feed.catalog_seq)} / AI ${show(cursor.seq)} · 확대 정합화 감사 대상 ${show(d.bulk_receipt_totals?.distinct_albums)}장</p></details>`);
}

// Unified read-only dashboard. Missing metrics are never displayed as zero.
export function renderUnifiedClassification(data){
 const u=object(data?.unified_classification),a=object(data?.autofill_progress),d=object(a.snapshot),t=object(d.totals),f=object(d.fields),b=object(u.breakdown);
 const n=v=>Number.isSafeInteger(v)&&v>=0?v:null,fmt=v=>n(v)===null?'—':v.toLocaleString('ko-KR');
 const ready=u.version===1&&u.state==='ready',coverage=d.state==='ADMIN_AUTOFILL_PROGRESS_OBSERVED',total=coverage?n(t.catalog_active):null;
 const metric=(label,value,sub='')=>`<article class="vr-u-metric"><span>${esc(label)}</span><strong>${fmt(value)}</strong><small>${esc(sub)}</small></article>`;
 const flags=ready?(u.automation_enabled?'자동 분류 설정 ON':'자동 분류 설정 OFF'):'운영 상태 미확인';
 const gate=ready?(u.gemini_assistance_enabled?(u.gemini_paid_enabled?'Gemini 보완 ON':'Gemini 저장 결과 활용'):'Gemini 보완 OFF'):'Gemini 상태 미확인';
 const budget=ready?(u.budget_valid?'호출 한도 유효':'호출 한도 갱신 필요'):'한도 미확인';
 const coverageRows=[['type','Album Type'],['genre','Genre'],['year','Original Year'],['label','Label']].map(([key,label])=>{const missing=coverage?n(f[key]?.effective_empty):null,filled=total!==null&&missing!==null&&missing<=total?total-missing:null,p=filled!==null&&total>0?filled/total*100:null;return `<div class="vr-u-field"><div><span>${label}</span><b>${p===null?'—':p.toFixed(1)+'%'}</b></div><div class="vr-u-track"><i style="width:${p===null?0:p}%"></i></div><small>등록 ${fmt(filled)} · 미등록 ${fmt(missing)}</small></div>`;}).join('');
 const days=ready&&Array.isArray(u.daily)?u.daily.filter(x=>typeof x?.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&['source','gemini','estimated'].every(k=>n(x[k])!==null)).slice(-7):[];
 const max=Math.max(1,...days.map(x=>x.source+x.gemini+x.estimated));
 const chart=days.length?`<div class="vr-u-chart" role="img" aria-label="최근 7일 자동 반영 건수">${days.map(x=>{const sum=x.source+x.gemini+x.estimated;return `<div class="vr-u-day"><b>${fmt(sum)}</b><div class="vr-u-column" aria-label="${esc(x.date)} ${fmt(sum)}건"><div style="height:${sum/max*100}%"><i style="flex:${x.source}"></i><i style="flex:${x.gemini}"></i><i style="flex:${x.estimated}"></i></div></div><small>${esc(x.date.slice(5))}</small></div>`;}).join('')}</div><div class="vr-u-legend"><span>출처 기반</span><span>Gemini 연계</span><span>Gemini 추정</span></div>`:'<p class="vr-u-muted">자동 반영 일별 집계 미제공</p>';
 const fieldNames={'current.category':'유형','current.genre':'장르','current.styles':'보조 장르','current.label':'레이블','current.original_year':'원발매년도','current.original_date':'원발매일'};
 const recent=ready&&Array.isArray(u.recent)?u.recent.slice(0,8):null;
 const history=recent?recent.map(x=>`<tr><td><strong>${esc(x.artist||'—')}</strong><small>${esc(x.title||'—')}</small></td><td>${esc(({source:'출처 기반',gemini:'Gemini 연계',estimated:'Gemini 추정'})[x.group]||'미구분')}</td><td>${esc(Array.isArray(x.fields)?x.fields.map(k=>fieldNames[k]||k).join(' · '):'—')}</td></tr>`).join(''):'';
 const settings=ready?`<p>Gemini 오늘 호출 ${fmt(u.today_calls)} / ${fmt(u.daily_requests)} · 누적 결과 미확정 ${fmt(u.unknown_calls)} · ${esc(budget)}</p><p>최근 실행 상태: ${esc(u.route_status?.state||'미확인')} · ${esc(u.route_status?.reason||'—')}</p>`:'<p>통합 운영 API가 연결되지 않았습니다.</p>';
 return `<section class="vr-unified-dashboard"><header><div><span class="vr-u-kicker">VINYL ROOM / AUTOMATION</span><h3>자동 분류 운영</h3><p>관리자 승인 없이 실제 Catalog에 반영된 기록</p></div><div class="vr-u-status"><b>${esc(flags)}</b><small>Confidence ${ready?fmt(u.confidence):'—'} · ${esc(gate)}</small></div></header>
 ${ready?'':'<p class="vr-u-alert" role="status">통합 집계 미연결 · 수치는 서버에서 제공된 경우에만 표시합니다.</p>'}
 <div class="vr-u-metrics">${metric('전체 활성 앨범',total,'Catalog 기준')}${metric('오늘 자동 반영',ready?u.today_albums:null,'중복 제외 앨범')}${metric('누적 자동 반영',ready?u.automatic_albums:null,'역대 중복 제외 앨범')}${metric('누적 반영 기록',ready?u.automatic_operations:null,'자동 적용 감사 원장')}</div>
 <div class="vr-u-columns"><section><h4>정보 등록률</h4>${coverageRows}<small class="vr-u-muted">정보 존재율 · 검증 완료율 아님</small></section><section><h4>최근 7일 자동 반영</h4>${chart}<div class="vr-u-breakdown"><span>출처 기반 <b>${ready?fmt(b.source):'—'}</b></span><span>Gemini 연계 <b>${ready?fmt(b.gemini):'—'}</b></span><span>Gemini 추정 <b>${ready?fmt(b.estimated):'—'}</b></span></div><small class="vr-u-muted">누적 감사 건수 · 추정은 외부 검증 아님</small></section></div>
 <section class="vr-u-history"><h4>최근 자동 반영</h4>${history?'<div class="table-wrap"><table><thead><tr><th>앨범</th><th>처리 방식</th><th>반영 항목</th></tr></thead><tbody>'+history+'</tbody></table></div>':'<p class="vr-u-muted">'+(recent?'반영 기록 없음':'반영 기록 미제공')+'</p>'}</section>
 <details data-vr-summary-detail="unified-ops"><summary>운영 상세 · 호출 한도 · 장애 및 기존 집계</summary>${settings}${renderAutofillProgress(data)}${renderAiOperationStatus(data)}</details><footer>실제 자동 적용 감사 기록의 이력 집계 · 복구된 과거 작업도 이력에 포함 · 관리자 수동 반영 제외</footer></section>`;
}
